head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
scwin.vScrenID = "ULDSTF20001.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_checkSearch = function() {
    if ($c.stf.getObjectValue(edt_BASE_DD).length != 8) {
        $c.win.alert("기준일을 선택하세요");
        edt_BASE_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_BASE_DD) > $c.ut.cGetToday("yyyymmdd")) {
        $c.win.alert("기준일이 현재일보다 큽니다.");
        edt_BASE_DD.focus();
        return false;
    }
    return true;
};
scwin.fn_list_sync_1 = function() {
    if (!scwin.fn_checkSearch()) return;

    //if (! fn_TrHoldyYn(dts_CHECK, getObjectValue(edt_BASE_DD)) ) {	return;	}

    var url = "/listingCommon.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=LISTSRH_MAINSTAT_CORPLISTING_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.select.mainstat.corplisting.condition" + "&{P}param01=" + $c.stf.getObjectValue(edt_BASE_DD) + "&{P}param02=" + $c.stf.getObjectValue(edt_BASE_DD) + "&{P}param03=" + $c.stf.getObjectValue(rdo_MARKET_TP_CD) + "&{P}param04=" + $c.stf.getObjectValue(edt_BASE_DD) + "&{P}param05=" + $c.stf.getObjectValue(edt_BASE_DD) + "&{P}param06=" + $c.stf.getObjectValue(rdo_MARKET_TP_CD);
    dts_List_1.DataID = encodeURI(url);
    dts_List_1.reset();
    $c.cm.ShowWin(grd_List_1);
    //grd_List_1.ColumnProp('DEP_NM', 'BgColor') = "Yellow";

};
scwin.fn_list_sync_2 = function() {
    if (!scwin.fn_checkSearch()) return;
    var url = "/listingCommon.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=LISTSRH_MAINSTAT_ADMISU_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    if ($c.stf.getObjectValue(rdo_MARKET_TP_CD) == '1') {
        url += "&queryId=lds.stf.lstsrch.select.mainstat.admisu.kse.condition" + "&{P}param01=" + $c.stf.getObjectValue(edt_BASE_DD) + "&{P}param02=" + $c.stf.getObjectValue(edt_BASE_DD) + "&{P}param03=" + $c.stf.getObjectValue(edt_BASE_DD) + "&{P}param04=" + $c.stf.getObjectValue(edt_BASE_DD);
    } else if ($c.stf.getObjectValue(rdo_MARKET_TP_CD) == '2') {
        url += "&queryId=lds.stf.lstsrch.select.mainstat.admisu.kosdaq.condition" + "&{P}param01=" + $c.stf.getObjectValue(edt_BASE_DD);
    }
    dts_List_2.DataID = encodeURI(url);
    dts_List_2.reset();
    $c.cm.ShowWin(grd_List_2);
};
scwin.fn_list_sync_3 = function() {
    var url = "/listingCommon.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=LISTSRH_MAINSTAT_NEWLISTING_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.select.mainstat.newlisting.condition" + "&{P}param01=" + $c.stf.getObjectValue(edt_BASE_YYYY) + "&{P}param02=" + $c.stf.getObjectValue(rdo_MARKET_TP_CD);
    dts_List_3.DataID = encodeURI(url);
    dts_List_3.reset();
    $c.cm.ShowWin(grd_List_3);
};
scwin.btn_Search_onclick = function() {
    var tIndex = MaxTab_01.getSelectedTabIndex();
    if (tIndex == 1) {
        scwin.fn_list_sync_1();
    } else if (tIndex == 2) {
        scwin.fn_list_sync_2();
    } else if (tIndex == 3) {
        scwin.fn_list_sync_3();
    }
};
scwin.MaxTab_01_OnSelChanged = function(nIndex) {
    if (MaxTab_01.getSelectedTabIndex() == 2) {
        $c.stf.showObj(panel_page, true);
        var Rows;
        if (dts_List_2.getTotalRow() > 0) {
            Rows = dts_List_2.getCellData(dts_List_2.getTotalRow(), "NO");
        } else {
            Rows = '';
        }
        $c.stf.FillGridHeaderTotalCnt(Rows, panel_page);
    } else {
        $c.stf.showObj(panel_page, false);
    }
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        $c.stf.showObj(panel_DD, true);
        $c.stf.showObj(panel_YYYY, false);
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        $c.stf.showObj(panel_DD, true);
        $c.stf.showObj(panel_YYYY, false);
    } else if (MaxTab_01.getSelectedTabIndex() == 3) {
        $c.stf.showObj(panel_DD, false);
        $c.stf.showObj(panel_YYYY, true);
    }
};
scwin.dts_List_1_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_List_1); //데이터 로딩중닫기 및 조회없음 처리	 

};
scwin.dts_List_1_OnLoadError = function() {
    $c.cm.CloseWin(0, grd_List_1);
    $c.stf.alert_error(dts_List_1);
};
scwin.dts_List_2_OnLoadCompleted = function(rowcount) {
    var Rows;
    if (dts_List_2.getTotalRow() > 0) {
        Rows = dts_List_2.getCellData(rowcount, "NO");
    } else {
        Rows = '';
    }
    $c.stf.FillGridHeaderTotalCnt(Rows, panel_page);
    $c.cm.CloseWin(rowcount, grd_List_2); //데이터 로딩중닫기 및 조회없음 처리	 

};
scwin.dts_List_2_OnLoadError = function() {
    $c.cm.CloseWin(0, grd_List_2);
    $c.stf.alert_error(dts_List_2);
};
scwin.dts_List_3_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_List_3); //데이터 로딩중닫기 및 조회없음 처리	 

};
scwin.dts_List_3_OnLoadError = function() {
    $c.cm.CloseWin(0, grd_List_3);
    $c.stf.alert_error(dts_List_3);
};
scwin.img_BASE_DD_onclick = function() {
    popUpCalendar2(edt_BASE_DD);
};
scwin.btn_Close_onclick = function() {
    self.close();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07); // 엑셀
    var tIndex = MaxTab_01.getSelectedTabIndex();
    if (tIndex == 1) {
        $c.data.downloadGridViewExcel(grd_List_1, "상장법인 현황", "", "8");
    } else if (tIndex == 2) {
        $c.data.downloadGridViewExcel(grd_List_2, "관리종목지정 현황", "", "8");
    } else if (tIndex == 3) {
        $c.data.downloadGridViewExcel(grd_List_3, "신규상장 법인현황", "", "8");
    }
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    edt_BASE_DD.setValue($c.ut.cGetToday("yyyymmdd"));
    $c.stf.showObj(panel_YYYY, false);
    edt_BASE_YYYY.setValue($c.ut.cGetToday("yyyymmdd").substring(0, 4));
    MaxTab_01.setSelectedTabIndex(1);
    if (js_market == "1" || js_market == "2") {
        $c.stf.showObj(panel_mkt_gubun, false);
        $c.stf.setObjectValue(rdo_MARKET_TP_CD, js_market);
    }
};
